import MermaidWrapper from '@/components/mdx/MermaidWrapper';

// Helper function to turn &quot; back into " and --&gt; back into -->
function decodeHtmlEntities(str) {
  if (!str) return '';
  return str
    .replace(/&quot;/g, '"')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&#x27;/g, "'")
    .replace(/&#x60;/g, '`');
}

export function useMDXComponents(components) {
  return {
    ...components,
    // Direct match for the custom <mermaid> element generated by your compiler!
    mermaid: ({ chart }) => {
      const cleanChart = decodeHtmlEntities(chart).trim();
      return <MermaidWrapper chart={cleanChart} />;
    },
  };
}
